/**
 * Validates the request form payload and normalizes it to the same shape as "Prepare email".
 *
 * Input item:  Webhook output ($json.body = form fields).
 * Output item: { uid, from_email, from_name, subject, body, source, skip, skip_reason }
 *
 * skip_reason "honeypot" = bot (answer with a fake success),
 * skip_reason "invalid input" = reject the request.
 */
const LIMITS = { name: 100, email: 254, subject: 150, message: 2000 };
const MIN_MESSAGE = 10;
const EMAIL_PATTERN = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/;

/**
 * Returns a trimmed string, or an empty string for non-string input.
 * @param {unknown} value
 * @returns {string}
 */
function text(value) {
  return typeof value === 'string' ? value.replace(/\r/g, '').trim() : '';
}

const data = $json.body ?? {};
const name = text(data.name).replace(/\s+/g, ' ');
const email = text(data.email).toLowerCase();
const subject = text(data.subject).replace(/\s+/g, ' ');
const message = text(data.message);

const isValid =
  name.length > 0 && name.length <= LIMITS.name &&
  EMAIL_PATTERN.test(email) && email.length <= LIMITS.email &&
  subject.length > 0 && subject.length <= LIMITS.subject &&
  message.length >= MIN_MESSAGE && message.length <= LIMITS.message;

let skipReason = '';
if (text(data.website)) skipReason = 'honeypot';
else if (!isValid) skipReason = 'invalid input';

return {
  json: {
    uid: null,
    from_email: email,
    from_name: name,
    subject,
    body: message,
    source: 'form',
    skip: skipReason !== '',
    skip_reason: skipReason,
  },
};

/**
 * Common entry point for emails and form requests.
 *
 * Input item:  output of "Should process?" (email) or "Form valid?" (form).
 * Output item: { uid, from_email, from_name, subject, body, source }
 *
 * All later nodes read the request from this node instead of from "Prepare email".
 */
return {
  json: {
    uid: $json.uid ?? null,
    from_email: $json.from_email,
    from_name: $json.from_name,
    subject: $json.subject,
    body: $json.body,
    source: $json.source ?? 'email',
  },
};

/**
 * Builds the notification mail for requests that end up in manual review.
 *
 * Output item: { subject, text }
 * The reason is derived from the nodes that ran in this execution.
 */
const MAX_BODY = 1500;

const req = $('Request').item.json;

let reason = 'The AI did not classify it as a work request.';
if ($('Send limit notice').isExecuted) reason = 'Daily limit reached. No ticket was created.';
else if ($('Send error notice').isExecuted) reason = 'Automatic processing failed. No ticket was created.';

const channel = req.source === 'form' ? 'request form' : 'email';

return {
  json: {
    subject: `[Join] Request needs review: ${reason.split('.')[0]}`,
    text: [
      `Reason: ${reason}`,
      `Channel: ${channel}`,
      `From: ${req.from_name} <${req.from_email}>`,
      `Subject: ${req.subject}`,
      '',
      String(req.body ?? '').slice(0, MAX_BODY),
    ].join('\n'),
  },
};
